-- Drop the invisible provenance and generator markers from every rendered output.
--
-- Evidence lives in `<!-- evidence: path:line -->` comments and the generator marker in
-- `<!-- generated by ... -->` comments in the markdown segments. They are the review-time audit
-- trail and they stay in the source under version control; the rendered deliverable must not carry
-- source paths in any format, so this filter removes them on the way out. This is deliberate: read
-- the comments in `docs/system/`, `docs/integrator/`, `docs/runbook/` and `docs/generated/`, never in `docs/_build`.
function RawBlock(el)
  if el.text:match("^%s*<!%-%-%s*evidence:") or el.text:match("^%s*<!%-%-%s*generated by") then
    return {}
  end
end

function RawInline(el)
  if el.text:match("^%s*<!%-%-%s*evidence:") or el.text:match("^%s*<!%-%-%s*generated by") then
    return {}
  end
end
